int Find(List<int> items, int limit, bool fast)
{
    if (fast)
        return items.Count;
    return items.FindIndex(x => x > limit);
}

int Sum1(List<int> xs)
{ int s = 0; foreach (var x in xs) s += x; return s; }

int Sum2(IEnumerable<int> xs)
{ int s = 0; foreach (var x in xs) s += x; return s; }

int Sum3(IReadOnlyList<int> xs)
{ int s = 0; for (int i = 0; i < xs.Count; i++) s += xs[i]; return s; }

string BuildReport(List<Order> orders)
{
    string result = "";
    foreach (var o in orders)
    {
        var line = $"{o.Id};{o.Total}";
        result += line + "\n";
    }
    return result;
}

async ValueTask<Item> GetAsync(string key)
{
    if (_cache.TryGetValue(key, out var item))
        return item;
    item = await LoadAsync(key);
    _cache[key] = item;
    return item;
}
